package httpx

import (
	"errors"
	"log"
	"net/http"
)

type AppError struct {
	Status  int
	Message string
}

func (e *AppError) Error() string {
	return e.Message
}

func Invalid(msg string) *AppError {
	return &AppError{Status: http.StatusBadRequest, Message: msg}
}

func NotFound(msg string) *AppError {
	return &AppError{Status: http.StatusNotFound, Message: msg}
}

func Conflict(msg string) *AppError {
	return &AppError{Status: http.StatusConflict, Message: msg}
}

func WriteError(w http.ResponseWriter, err error) {
	var appErr *AppError
	if errors.As(err, &appErr) {
		WriteJSON(w, appErr.Status, map[string]string{"error": appErr.Message})
		return
	}
	log.Printf("unexpected error: %v", err)
	WriteJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal server error"})
}

package campaign_test

import (
	"context"
	"encoding/json"
	"os"
	"strconv"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/campaign"
)

// TestConcurrentImpressions_NeverOverspend proves the Definition of Done
// requirement: under heavy concurrent load against a single campaign, spent
// never exceeds budget. It runs against the real Postgres started by
// docker compose, per CLAUDE.md's testing approach (no mocks).
func TestConcurrentImpressions_NeverOverspend(t *testing.T) {
	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		t.Skip("DATABASE_URL not set; run against the Postgres started by docker compose")
	}

	ctx := context.Background()
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		t.Fatalf("connecting to database: %v", err)
	}
	defer pool.Close()

	repo := campaign.NewRepository(pool)
	svc := campaign.NewService(repo)

	const budget = 50
	const concurrency = 300

	created, err := svc.Create(ctx, campaign.CreateInput{
		Title:     "concurrency test",
		Budget:    json.Number(strconv.Itoa(budget)),
		StartDate: time.Now().Add(-time.Hour),
		EndDate:   time.Now().Add(time.Hour),
	})
	if err != nil {
		t.Fatalf("creating test campaign: %v", err)
	}
	t.Cleanup(func() {
		_ = svc.Delete(context.Background(), created.ID)
	})

	var successes int64
	var wg sync.WaitGroup
	wg.Add(concurrency)
	for i := 0; i < concurrency; i++ {
		go func() {
			defer wg.Done()
			if _, err := svc.RecordImpression(ctx, created.ID); err == nil {
				atomic.AddInt64(&successes, 1)
			}
		}()
	}
	wg.Wait()

	if successes != budget {
		t.Fatalf("expected exactly %d successful impressions, got %d", budget, successes)
	}

	final, err := svc.Get(ctx, created.ID)
	if err != nil {
		t.Fatalf("fetching final campaign state: %v", err)
	}
	if final.Spent != budget {
		t.Fatalf("expected spent == %d, got %d", budget, final.Spent)
	}
	if final.Spent > final.Budget {
		t.Fatalf("budget went negative: spent=%d budget=%d", final.Spent, final.Budget)
	}
	if final.Status != campaign.StatusPaused {
		t.Fatalf("expected status %q after exhausting budget, got %q", campaign.StatusPaused, final.Status)
	}
}

package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/campaign"
	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/migrations"
)

func main() {
	if err := run(); err != nil {
		log.Fatal(err)
	}
}

func run() error {
	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		return errors.New("DATABASE_URL environment variable is required")
	}

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	if err := runMigrations(databaseURL); err != nil {
		return fmt.Errorf("running migrations: %w", err)
	}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return fmt.Errorf("creating pgxpool: %w", err)
	}
	defer pool.Close()

	repo := campaign.NewRepository(pool)
	svc := campaign.NewService(repo)
	h := campaign.NewHandler(svc)

	mux := http.NewServeMux()
	mux.HandleFunc("POST /campaigns", h.Create)
	mux.HandleFunc("GET /campaigns", h.List)
	mux.HandleFunc("GET /campaigns/{id}", h.Get)
	mux.HandleFunc("PATCH /campaigns/{id}", h.Update)
	mux.HandleFunc("DELETE /campaigns/{id}", h.Delete)
	mux.HandleFunc("POST /campaigns/{id}/pause", h.Pause)
	mux.HandleFunc("POST /campaigns/{id}/resume", h.Resume)
	mux.HandleFunc("POST /campaigns/{id}/end", h.End)
	mux.HandleFunc("POST /impression/{id}", h.Impression)
	mux.HandleFunc("GET /stats/{id}", h.Stats)

	server := &http.Server{
		Addr:    ":" + port,
		Handler: mux,
	}

	errCh := make(chan error, 1)
	go func() {
		log.Printf("listening on :%s", port)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
		}
	}()

	select {
	case err := <-errCh:
		return fmt.Errorf("server error: %w", err)
	case <-ctx.Done():
		log.Println("shutdown signal received")
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("server shutdown: %w", err)
	}

	return nil
}

func runMigrations(databaseURL string) error {
	db, err := sql.Open("pgx", databaseURL)
	if err != nil {
		return fmt.Errorf("opening db for migrations: %w", err)
	}
	defer db.Close()

	goose.SetBaseFS(migrations.FS)

	if err := goose.SetDialect("postgres"); err != nil {
		return fmt.Errorf("setting goose dialect: %w", err)
	}

	if err := goose.Up(db, "."); err != nil {
		return fmt.Errorf("goose up: %w", err)
	}

	return nil
}

