// changes which tab a row lands in, not what it displays.
export function tabBucket(campaign: Campaign): CampaignStatus {
  return displayStatus(campaign) === 'Ended' ? 'completed' : campaign.status;
}
```
`'Scheduled'` needs no special case: when `displayStatus` returns `'Scheduled'`, `campaign.status` is already `'active'`, so it falls through unchanged and stays under Active exactly as today.

### `src/pages/CampaignsPage.tsx` — filter by the new helper instead of raw status

```ts
