1	import { useState } from 'react';
2	import type { FormEvent } from 'react';
3	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
4	import { useNavigate, useParams } from 'react-router';
5	
6	import { request } from '../api/client';
7	import StatusBadge from '../components/StatusBadge';
8	import type { Campaign, Stats, UpdateCampaignInput } from '../types';
9	import './CampaignDetailPage.css';
10	
11	// datetime-local inputs need "YYYY-MM-DDTHH:mm" in the viewer's local time;
12	// the API returns UTC RFC 3339. Using the Date object's local getters (not
13	// the UTC ones) renders the browser's local wall-clock view of that instant
14	// — the exact inverse of new Date(localString).toISOString().
15	function toDatetimeLocalValue(iso: string): string {
16	  const d = new Date(iso);
17	  const pad = (n: number) => String(n).padStart(2, '0');
18	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
19	}
20	
21	export default function CampaignDetailPage() {
22	  const { id } = useParams();
23	  const queryClient = useQueryClient();
24	  const navigate = useNavigate();
25	
26	  const campaignQuery = useQuery({
27	    queryKey: ['campaign', id],
28	    queryFn: () => request<Campaign>(`/api/campaigns/${id}`),
29	  });
30	
31	  const statsQuery = useQuery({
32	    queryKey: ['stats', id],
33	    queryFn: () => request<Stats>(`/api/stats/${id}`),
34	    refetchInterval: 2000,
35	  });
36	
37	  // Tracks which fetched campaign the edit form's fields currently reflect,
38	  // so they re-sync whenever the query returns a genuinely new object (first
39	  // load, a save, or another action's refetch) without needing an effect —
40	  // setting state during render like this is React's documented pattern for
41	  // "adjust state when a prop/query result changes".
42	  const [syncedCampaign, setSyncedCampaign] = useState<Campaign | null>(null);
43	  const [budgetDelta, setBudgetDelta] = useState('0');
44	  const [startDate, setStartDate] = useState('');
45	  const [endDate, setEndDate] = useState('');
46	
47	  if (campaignQuery.data && campaignQuery.data !== syncedCampaign) {
48	    setSyncedCampaign(campaignQuery.data);
49	    setBudgetDelta('0');
50	    setStartDate(toDatetimeLocalValue(campaignQuery.data.start_date));
51	    setEndDate(toDatetimeLocalValue(campaignQuery.data.end_date));
52	  }
53	
54	  function invalidateDetail() {
55	    queryClient.invalidateQueries({ queryKey: ['campaign', id] });
56	    queryClient.invalidateQueries({ queryKey: ['stats', id] });
57	  }
58	
59	  const edit = useMutation({
60	    mutationFn: (input: UpdateCampaignInput) =>
61	      request<Campaign>(`/api/campaigns/${id}`, { method: 'PATCH', body: input }),
62	    onSuccess: invalidateDetail,
63	  });
64	
65	  const pause = useMutation({
66	    mutationFn: () => request<Campaign>(`/api/campaigns/${id}/pause`, { method: 'POST' }),
67	    onSuccess: invalidateDetail,
68	  });
69	
70	  const resume = useMutation({
71	    mutationFn: () => request<Campaign>(`/api/campaigns/${id}/resume`, { method: 'POST' }),
72	    onSuccess: invalidateDetail,
73	  });
74	
75	  const end = useMutation({
76	    mutationFn: () => request<Campaign>(`/api/campaigns/${id}/end`, { method: 'POST' }),
77	    onSuccess: invalidateDetail,
78	  });
79	
80	  const del = useMutation({
81	    mutationFn: () => request<void>(`/api/campaigns/${id}`, { method: 'DELETE' }),
82	    onSuccess: () => {
83	      queryClient.invalidateQueries({ queryKey: ['campaigns'] });
84	      navigate('/');
85	    },
86	  });
87	
88	  const impression = useMutation({
89	    mutationFn: () => request<Campaign>(`/api/impression/${id}`, { method: 'POST' }),
90	    onSuccess: invalidateDetail,
91	  });
92	
93	  if (!id) {
94	    return <p>Invalid campaign id.</p>;
95	  }
96	
97	  if (campaignQuery.isLoading) {
98	    return <p>Loading…</p>;
99	  }
100	
101	  if (campaignQuery.error) {
102	    return <p>{campaignQuery.error.message}</p>;
103	  }
104	
105	  const campaign = campaignQuery.data;
106	  if (!campaign) {
107	    return <p>Campaign not found.</p>;
108	  }
109	
110	  const isCompleted = campaign.status === 'completed';
111	
112	  // Both derived from the same hypothetical, unsaved state — shown together
113	  // so they can't be read as contradicting the still-live "Remaining" figure
114	  // in the Live Stats panel below, which reflects the actual, saved budget
115	  // until this form is actually submitted.
116	  const previewBudget = campaign.budget + (Number(budgetDelta) || 0);
117	  const previewRemaining = previewBudget - campaign.spent;
118	
119	  function handleSave(e: FormEvent) {
120	    e.preventDefault();
121	    if (!campaign || !startDate || !endDate) {
122	      return;
123	    }
124	
125	    // Only send fields that actually changed. The backend treats a date
126	    // field's mere presence in the request as "touching" it (gating on
127	    // paused-only), so resending the current dates unchanged alongside a
128	    // budget-only edit would incorrectly trip that guard on an active
129	    // campaign — this keeps PATCH's partial-update contract honest.
130	    const input: UpdateCampaignInput = {};
131	    const delta = Number(budgetDelta) || 0;
132	    if (delta !== 0) {
133	      input.budget = campaign.budget + delta;
134	    }
135	    if (startDate !== toDatetimeLocalValue(campaign.start_date)) {
136	      input.start_date = new Date(startDate).toISOString();
137	    }
138	    if (endDate !== toDatetimeLocalValue(campaign.end_date)) {
139	      input.end_date = new Date(endDate).toISOString();
140	    }
141	
142	    if (Object.keys(input).length === 0) {
143	      return;
144	    }
145	
146	    edit.mutate(input);
147	  }
148	
149	  return (
150	    <div>
151	      <h1>{campaign.title}</h1>
152	
153	      <div className="detail-card">
154	        <div className="detail-grid">
155	          <div className="detail-info">
156	            <p>
157	              Status: <StatusBadge campaign={campaign} />
158	            </p>
159	
160	            <form className="edit-form" onSubmit={handleSave}>
161	              <label>
162	                Adjust budget by
163	                <input
164	                  type="number"
165	                  value={budgetDelta}
166	                  onChange={(e) => setBudgetDelta(e.target.value)}
167	                  step={1}
168	                  disabled={isCompleted}
169	                />
170	              </label>
171	              <p className="field-hint">
172	                Positive to add, negative to reduce. If saved: budget {previewBudget.toLocaleString()}, remaining{' '}
173	                {previewRemaining.toLocaleString()}.
174	              </p>
175	
176	              <label>
177	                Start date
178	                <input
179	                  type="datetime-local"
180	                  value={startDate}
181	                  onChange={(e) => setStartDate(e.target.value)}
182	                  required
183	                  disabled={isCompleted}
184	                />
185	              </label>
186	
187	              <label>
188	                End date
189	                <input
190	                  type="datetime-local"
191	                  value={endDate}
192	                  onChange={(e) => setEndDate(e.target.value)}
193	                  required
194	                  disabled={isCompleted}
195	                />
196	              </label>
197	
198	              {edit.error && <p className="action-error">{edit.error.message}</p>}
199	
200	              <button className="btn-primary" type="submit" disabled={isCompleted || edit.isPending}>
201	                {edit.isPending ? 'Saving…' : 'Save changes'}
202	              </button>
203	            </form>
204	          </div>
205	
206	          <div className="detail-side">
