// datetime-local inputs need "YYYY-MM-DDTHH:mm" in the viewer's local time;
// the API returns UTC RFC 3339. Using the Date object's local getters (not
// the UTC ones) renders the browser's local wall-clock view of that instant
// — the exact inverse of new Date(localString).toISOString().
function toDatetimeLocalValue(iso: string): string {
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

