.tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.tab {
  padding: 8px 16px;
  border: none;
  background: none;
  font: inherit;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
}

.tab-active {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.table-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  overflow: hidden;
}

.campaigns-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
}

.campaigns-table th,
.campaigns-table td {
  text-align: left;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
}

.campaigns-table th {
  color: var(--text-muted);
  font-weight: 500;
}

.campaigns-table tbody tr:last-child td {
  border-bottom: none;
}

.campaigns-table tbody tr:not(.empty-row) {
  cursor: pointer;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
}

.campaigns-table tbody tr:not(.empty-row):hover {
  background: var(--surface-hover);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}

.campaigns-table th:nth-child(1) {
  width: 25%;
}

.campaigns-table th:nth-child(2),
.campaigns-table th:nth-child(3),
.campaigns-table th:nth-child(4),
.campaigns-table td:nth-child(2),
.campaigns-table td:nth-child(3),
.campaigns-table td:nth-child(4) {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.campaigns-table th:nth-child(5),
.campaigns-table td:nth-child(5) {
  text-align: right;
}

.title-cell {
  max-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
